import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { fetchProfile } from "../services/authApi";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState(null);
  const [lastCheckedAt, setLastCheckedAt] = useState(0);

  async function refreshProfile() {
    setLoading(true);
    try {
      const res = await fetchProfile();
      setProfile(res.ok ? res.profile : null);
      setLastCheckedAt(Date.now());
      return res.ok;
    } catch (e) {
      setProfile(null);
      setLastCheckedAt(Date.now());
      return false;
    } finally {
      setLoading(false);
    }
  }

  function logoutLocal() {
    setProfile(null);
    setLastCheckedAt(Date.now());
  }

  useEffect(() => {
    refreshProfile();
  }, []);

  useEffect(() => {
    const t = setTimeout(() => {
      if (!profile) refreshProfile();
    }, 350);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const onPopState = () => {
      const now = Date.now();
      if (now - lastCheckedAt > 2000) refreshProfile();
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [lastCheckedAt]);

  const value = useMemo(
    () => ({ loading, profile, refreshProfile, logoutLocal }),
    [loading, profile]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}
